/**
 * Sprint 19R — Decision Support Candidate Handler: fixture corpus.
 *
 * 50 realistic PMFreak PM phrases across the ten `DecisionSupportDecisionType` values, used to test
 * the pure, isolated candidate handler in `src/lib/playbook-engine/conversation/decision-support/`.
 * This corpus is unrelated to production routing — it never touches the router, composer, any
 * handler, the endpoint, or the Sprint 10R adapter mapping. Every case's `shouldExecuteAction`
 * expectation is implicit and always false (the candidate handler never executes anything).
 *
 * `expectedEvidenceKeywords`/`expectedTradeoffKeywords`/`expectedRiskKeywords` are lowercase,
 * accent-free substrings expected to appear somewhere in the corresponding result field once both
 * sides are run through `normalizeDecisionSupportInput()` — see the test file for the exact
 * matching helper.
 */

export type DecisionSupportHandlerCase = {
  id: string;
  input: string;
  expectedDecisionType:
    | "choose_between_options"
    | "escalate_or_wait"
    | "close_or_continue"
    | "bill_or_wait"
    | "accept_or_mitigate_risk"
    | "change_vendor_or_continue"
    | "approve_or_request_evidence"
    | "prioritize_next_step"
    | "identify_missing_decision"
    | "general_decision_support";
  expectedMinOptions: number;
  expectedEvidenceKeywords: string[];
  expectedTradeoffKeywords: string[];
  expectedRiskKeywords: string[];
  expectedConfidence: "low" | "medium" | "high";
  shouldAskClarifyingQuestion: boolean;
  notes?: string;
};

